import configparser
import os
import shutil

def task_func(config_file_path, archieve_dir='/home/user/archive'):
    if not os.path.isfile(config_file_path):
        raise FileNotFoundError(f"Config file not found: {config_file_path}")

    config = configparser.ConfigParser()
    read_files = config.read(config_file_path)
    if not read_files or 'Project' not in config or 'directory' not in config['Project']:
        raise ValueError("Invalid configuration file format. Expected [Project] section with directory=...")

    project_dir = config['Project']['directory'].strip()
    if not project_dir:
        raise ValueError("Project directory path is empty")

    if not os.path.isabs(project_dir):
        project_dir = os.path.abspath(
            os.path.join(os.path.dirname(os.path.abspath(config_file_path)), project_dir)
        )

    if not os.path.isdir(project_dir):
        raise FileNotFoundError(f"Project directory not found: {project_dir}")

    os.makedirs(archieve_dir, exist_ok=True)

    project_name = os.path.basename(os.path.normpath(project_dir))
    if not project_name:
        raise ValueError("Invalid project directory path")

    archive_base = os.path.join(archieve_dir, project_name)

    try:
        shutil.make_archive(
            archive_base,
            'zip',
            root_dir=os.path.dirname(project_dir),
            base_dir=project_name
        )
    except Exception as exc:
        raise Exception(f"Failed to create ZIP archive: {exc}")

    return True
